'use strict';

const crypto = require('node:crypto');
const { invalid, conflict } = require('../lib/errors');

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const MIN_PASSWORD_LENGTH = 8;

function hashPassword(password, salt) {
  return crypto.scryptSync(password, salt, 32).toString('hex');
}

function normalizeEmail(email) {
  return typeof email === 'string' ? email.trim().toLowerCase() : '';
}

function toPublic(user) {
  return { id: user.id, email: user.email, name: user.name, role: user.role, createdAt: user.createdAt };
}

function createUserService({ store }) {
  function register({ email, password, name }, role = 'customer') {
    const normalized = normalizeEmail(email);
    if (!EMAIL_PATTERN.test(normalized)) throw invalid('a valid email is required');
    if (typeof password !== 'string' || password.length < MIN_PASSWORD_LENGTH) {
      throw invalid(`password must be at least ${MIN_PASSWORD_LENGTH} characters`);
    }
    if (typeof name !== 'string' || name.trim() === '') throw invalid('name is required');
    if (store.findOne('users', (user) => user.email === normalized)) throw conflict('email already registered');
    const salt = crypto.randomBytes(16).toString('hex');
    return toPublic(store.insert('users', {
      email: normalized,
      name: name.trim(),
      role,
      salt,
      passwordHash: hashPassword(password, salt),
      createdAt: new Date().toISOString(),
    }));
  }

  function verifyCredentials(email, password) {
    if (typeof password !== 'string') return null;
    const normalized = normalizeEmail(email);
    const user = store.findOne('users', (candidate) => candidate.email === normalized);
    if (!user) return null;
    const expected = Buffer.from(user.passwordHash, 'hex');
    const actual = Buffer.from(hashPassword(password, user.salt), 'hex');
    return crypto.timingSafeEqual(expected, actual) ? toPublic(user) : null;
  }

  function find(id) {
    const user = store.get('users', id);
    return user ? toPublic(user) : null;
  }

  return { register, verifyCredentials, find, toPublic };
}

module.exports = { createUserService };
'use strict';

const fs = require('node:fs');
const http = require('node:http');
const os = require('node:os');
const path = require('node:path');
const { createApp } = require('../src/app');

const ADMIN = { email: 'admin@example.com', password: 'admin-password', name: 'Admin' };
const PASSWORD = 'correct-horse';

async function startApp(t, options = {}) {
  const reportDir = fs.mkdtempSync(path.join(os.tmpdir(), 'orders-reports-'));
  const app = createApp({ secret: 'test-secret', reportDir, admin: ADMIN, ...options });
  const port = await app.listen(0);
  t.after(async () => {
    await app.close();
    fs.rmSync(reportDir, { recursive: true, force: true });
  });

  function call(method, urlPath, { body, token } = {}) {
    return new Promise((resolve, reject) => {
      const payload = body === undefined ? undefined : JSON.stringify(body);
      const headers = {};
      if (payload !== undefined) headers['content-type'] = 'application/json';
      if (token) headers.authorization = `Bearer ${token}`;
      const req = http.request({ host: '127.0.0.1', port, method, path: urlPath, headers, agent: false }, (res) => {
        const chunks = [];
        res.on('data', (chunk) => chunks.push(chunk));
        res.on('end', () => {
          const text = Buffer.concat(chunks).toString('utf8');
          const isJson = (res.headers['content-type'] || '').startsWith('application/json');
          resolve({ status: res.statusCode, body: isJson && text ? JSON.parse(text) : undefined, text });
        });
      });
      req.on('error', reject);
      req.end(payload);
    });
  }

  async function login(email, password = PASSWORD) {
    const res = await call('POST', '/sessions', { body: { email, password } });
    return res.body.token;
  }

  async function signUp(email, name = 'Customer') {
    await call('POST', '/users', { body: { email, password: PASSWORD, name } });
    return login(email);
  }

  return { call, login, signUp, reportDir, adminToken: await login(ADMIN.email, ADMIN.password) };
}

module.exports = { startApp, PASSWORD };
'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { startApp } = require('./helpers');

const ITEMS = [
  { sku: 'BOOK-1', unitPrice: 12.5, quantity: 2 },
  { sku: 'PEN-3', unitPrice: 5, quantity: 1 },
];

test('creating an order computes its total', async (t) => {
  const { call, signUp } = await startApp(t);
  const token = await signUp('alice@example.com');
  const res = await call('POST', '/orders', { token, body: { items: ITEMS } });
  assert.equal(res.status, 201);
  assert.equal(res.body.total, 30);
  assert.equal(res.body.status, 'pending');
  assert.equal(res.body.items.length, 2);
