'use strict';

const { invalid } = require('./errors');

function isAmount(value) {
  return typeof value === 'number'
    && Number.isFinite(value)
    && value > 0
    && Number.isSafeInteger(Math.round(value * 100))
    && Math.round(value * 100) > 0
    && value === Math.round(value * 100) / 100;
}

function sumLines(items) {
  const cents = items.reduce((total, item) => {
    const line = Math.round(item.unitPrice * 100) * item.quantity;
    if (!Number.isSafeInteger(line) || !Number.isSafeInteger(total + line)) {
      throw invalid('order total exceeds the supported amount');
    }
    return total + line;
  }, 0);
  const total = cents / 100;
  if (Math.round(total * 100) !== cents) throw invalid('order total exceeds the supported precision');
  return total;
}

module.exports = { isAmount, sumLines };
